using U=uint32_t;using B=uint8_t;
float bits(U x){float y;memcpy(&y,&x,4);return y;}U raw(float x){U y;memcpy(&y,&x,4);return y;}
float rcp(float x){U u=raw(x),s=u&0x80000000,e=(u>>23)&255,f=u&0x7fffff;if(e==255)return bits(f?u|0x400000:s);int ee=e;if(!e){if(f<0x200000)return bits(s|0x7f800000);ee=1;while(f<0x800000){f*=2;ee--;}f&=0x7fffff;}U bin=256+(f>>15),est=((524288/(bin*2+1))+1)/2;int re=253-ee;U rf=(est&255)<<15;if(re<=0){rf=(0x800000|rf)>>(1-re);re=0;}return bits(s|(U(re)<<23)|rf);}
B byte(float v){if(!std::isfinite(v))return 0;long x=(long)std::nearbyint(v);return B(x&255);}
struct C{float o,a,f;};
C controls(double o,double a,double f,bool alias){if(!std::isfinite(o)||!std::isfinite(a)||!std::isfinite(f)||o<0||o>1||a<0||a>1||f<0||f>1)throw std::runtime_error("controls");C c{float(o),float(a),float(f)};if(alias&&float(std::abs(float(c.o-c.a))*100000.f)<=std::fmin(std::abs(c.o),std::abs(c.a)))c.a=c.o;return c;}
void pixel(const B*s,const B*d,B*out,int op,C c,int mask){constexpr float inv=1.f/255.f,inv2=1.f/65025.f;float alpha,S,blend;memcpy(out,d,4);if(op==0){S=float(s[3]*c.o);if(mask>=0)S=float(S*float(mask*inv));if(S==0)return;float D=d[3];if(D==255){alpha=D;blend=float(S*inv);}else if(D==0){alpha=S;blend=1;}else{float t=float(S*float(255-D));alpha=std::fma(t,inv,D);blend=float(S*rcp(alpha));}for(int k=0;k<3;k++)out[k]=blend==1?s[k]:blend==0?d[k]:byte(std::fma(blend,float(int(s[k])-int(d[k])),float(d[k])));}else{bool hard=op==2;if(hard){c.o=float(c.f*c.o);c.a=float(c.f*c.a);}float D=d[3]==0?0:float(d[3]*inv),M=mask<0?float(s[3]*inv):float(float(mask*inv2)*s[3]);S=float(c.o*M);for(int k=0;k<3;k++)out[k]=d[3]==0?s[k]:byte(std::fma(S,float(int(s[k])-int(d[k])),float(d[k])));float full=c.a>c.o?(c.a>D?std::fma(float(D/c.a),float(c.a-S),S):D):(c.o>D?std::fma(float(c.o-D),M,D):D);if(c.f==1)alpha=float(full*255);else{float zero=hard?std::fma(-D,S,float(D+S)):D;alpha=float(std::fma(c.f,float(full-zero),zero)*255);}}out[3]=byte(alpha);}
template<class T>T read(){T v;if(fread(&v,sizeof(v),1,stdin)!=1)throw std::runtime_error("truncated");return v;}
void bytes(void*p,size_t n){if(fread(p,1,n,stdin)!=n)throw std::runtime_error("truncated bytes");}void write(const void*p,size_t n){if(fwrite(p,1,n,stdout)!=n)throw std::runtime_error("write");}
U fnv(const std::vector<B>&p){U h=2166136261u;for(B x:p)h=(h^x)*16777619u;return h;}
int main(){try{std::fesetround(FE_TONEAREST);U mode=read<U>();if(mode==1){U count=read<U>();if(count>1000000)throw std::runtime_error("count");for(U i=0;i<count;i++){int op=read<int>(),mask=read<int>(),alias=read<int>();double o=read<double>(),a=read<double>(),f=read<double>();if(op<0||op>2||mask< -1||mask>255)throw std::runtime_error("point");B s[4],d[4],out[4];bytes(s,4);bytes(d,4);pixel(s,d,out,op,controls(o,a,f,alias),mask);write(out,4);}}else if(mode==3){U count=read<U>();if(count>10000)throw std::runtime_error("count");for(U i=0;i<count;i++){double o=read<double>(),a=read<double>(),f=read<double>();C c=controls(o,a,f,true);U result[3]={raw(c.o),raw(c.a),raw(c.f)};write(result,12);}}else if(mode==2){int w=read<int>(),h=read<int>(),wash=read<int>();double outer=read<double>();if(w<1||h<1||w>2048||h>2048)throw std::runtime_error("plane");std::vector<B> base(size_t(w)*h*4),local(base.size()),preview(base.size());bytes(base.data(),base.size());if(!wash)local=base;U commands=read<U>();if(commands>100000)throw std::runtime_error("commands");uint64_t work=0;for(U z=0;z<commands;z++){int kind=read<int>();if(kind==1){int op=read<int>(),x=read<int>(),y=read<int>(),mw=read<int>(),mh=read<int>(),mx=read<int>(),my=read<int>();double o=read<double>(),a=read<double>(),f=read<double>();B rgb[3];bytes(rgb,3);if(op<0||op>2||x< -100000000||x>100000000||y< -100000000||y>100000000||mx<0||mx>1||my<0||my>1||mw<1||mh<1||mw>4096||mh>4096)throw std::runtime_error("mask");work+=uint64_t(mw)*mh;if(work>200000000)throw std::runtime_error("work");std::vector<B> mask(size_t(mw)*mh);bytes(mask.data(),mask.size());C c=controls(o,a,f,false);for(int yy=std::max(0,y);yy<std::min(h,y+mh);yy++)for(int xx=std::max(0,x);xx<std::min(w,x+mw);xx++){int ix=mx?mw-1-(xx-x):xx-x,iy=my?mh-1-(yy-y):yy-y;B s[4]={rgb[0],rgb[1],rgb[2],mask[size_t(iy)*mw+ix]},out[4];size_t off=(size_t(h-1-yy)*w+xx)*4;pixel(s,local.data()+off,out,op,c,-1);memcpy(local.data()+off,out,4);}}else if(kind==2){if(wash){C c=controls(outer,outer,1,false);for(size_t i=0;i<local.size();i+=4)pixel(local.data()+i,base.data()+i,preview.data()+i,0,c,-1);}U a=fnv(local),b=fnv(wash?preview:local);write(&a,4);write(&b,4);}else throw std::runtime_error("command");}if(wash){C c=controls(outer,outer,1,false);for(size_t i=0;i<local.size();i+=4)pixel(local.data()+i,base.data()+i,preview.data()+i,0,c,-1);}write((wash?preview:local).data(),local.size());}else throw std::runtime_error("mode");return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
